#### 3.3 加载地图数据

```
function loadMapData(cityCode) {
    // 检查缓存
    if (mapDataCache[cityCode]) {
        updateMap(cityCode, mapDataCache[cityCode]);
        return;
    }

    // 显示加载状态
    myChart.showLoading({
        text: '加载地图数据中...',
        color: '#fff',
        textColor: '#fff',
        maskColor: 'rgba(0, 0, 0, 0.5)'
    });

    // 从阿里云DataV获取地图数据
    fetch(`https://geo.datav.aliyun.com/areas_v3/bound/geojson?code=${cityCode}_full`)
        .then(res => res.json())
        .then(data => {
            mapDataCache[cityCode] = data;
            updateMap(cityCode, data);
        })
        .catch(error => {
            console.error('地图数据加载失败:', error);
            myChart.hideLoading();
        });
}

```

