                borderColor: "#c0f3fb",
                borderWidth: 0.8
            }
        }
    },
    // 重影层
    {
        zlevel: -1,
        layoutCenter: ["50%", "51%"],
        itemStyle: {
            normal: {
                borderColor: "rgba(58,149,253,0.8)",
                shadowColor: "rgba(172, 122, 255,0.5)",
                shadowOffsetY: 5,
                shadowBlur: 15
